begin;

create table public.learning_central_studies_v2_candidates (
  id uuid primary key default extensions.uuid_generate_v4(),
  journey_code text not null,
  content_version text not null,
  subject_area text not null check (subject_area in ('MATHEMATICS', 'PORTUGUESE', 'SCIENCE')),
  grade_level smallint not null check (grade_level = 6),
  official_skill_code text not null,
  snapshot_fingerprint text not null check (snapshot_fingerprint ~ '^[0-9a-f]{64}$'),
  payload jsonb not null check (jsonb_typeof(payload) = 'object'),
  review_status text not null default 'PEDAGOGICAL_REVIEW_PENDING' check (review_status in ('PEDAGOGICAL_REVIEW_PENDING', 'PEDAGOGICAL_REVIEWED', 'CHANGES_REQUESTED')),
  publication_status text not null default 'STAGING' check (publication_status = 'STAGING'),
  reviewer_profile_id uuid references public.profiles(id) on delete set null,
  reviewer_id_snapshot uuid,
  reviewer_name text,
  reviewer_email text,
  reviewed_at timestamptz,
  review_notes text,
  review_checklist jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (journey_code, content_version),
  constraint learning_central_studies_v2_review_state_check check (
    (review_status = 'PEDAGOGICAL_REVIEW_PENDING' and reviewed_at is null and reviewer_id_snapshot is null)
    or (review_status in ('PEDAGOGICAL_REVIEWED', 'CHANGES_REQUESTED') and reviewed_at is not null and reviewer_id_snapshot is not null)
  )
);

create table public.learning_central_studies_v2_review_events (
  id uuid primary key default extensions.uuid_generate_v4(),
  candidate_id uuid not null references public.learning_central_studies_v2_candidates(id) on delete restrict,
  journey_code text not null,
  content_version text not null,
  snapshot_fingerprint text not null check (snapshot_fingerprint ~ '^[0-9a-f]{64}$'),
  decision text not null check (decision in ('APPROVED_FOR_INTEGRATION', 'CHANGES_REQUESTED')),
  notes text not null,
  checklist jsonb not null default '{}'::jsonb,
  reviewer_profile_id uuid references public.profiles(id) on delete set null,
  reviewer_id_snapshot uuid not null,
  reviewer_name text not null,
  reviewer_email text not null,
  reviewed_at timestamptz not null default now()
);

create index learning_central_studies_v2_candidate_queue_idx
  on public.learning_central_studies_v2_candidates(subject_area, grade_level, review_status, updated_at desc);
create index learning_central_studies_v2_review_events_history_idx
  on public.learning_central_studies_v2_review_events(journey_code, content_version, reviewed_at desc);

alter table public.learning_central_studies_v2_candidates enable row level security;
alter table public.learning_central_studies_v2_review_events enable row level security;
revoke all on public.learning_central_studies_v2_candidates, public.learning_central_studies_v2_review_events from public, anon, authenticated;

insert into public.learning_central_studies_v2_candidates(
  journey_code, content_version, subject_area, grade_level, official_skill_code, snapshot_fingerprint, payload
) values
  ('CEV2_EF06CI01_MISTURAS_01', 'central-estudos-v2-candidate-2026-10-25.2', 'SCIENCE', 6, 'EF06CI01', '43ff9e8b544d12edc791a0243feb3154a58320722b69b7dda44571617f611137', '{"journeyCode":"CEV2_EF06CI01_MISTURAS_01","journeyTitle":"Misturas homogêneas e heterogêneas","subject":"SCIENCE","grade":6,"officialSkillCode":"EF06CI01","skill":"SCIENCE_MIXTURE_CLASSIFICATION","unitCode":"SCI_MATERIAIS","unitTitle":"Materiais e transformações","officialText":"Classificar como homogênea ou heterogênea a mistura de dois ou mais materiais (água e sal, água e óleo, água e areia etc.).","lesson":{"title":"Observar fases para classificar misturas","estimatedMinutes":18,"introduction":"Ao preparar água com sal, os grãos podem deixar de ser visíveis. Em um copo com água e óleo, aparecem camadas. Observar o sistema com cuidado ajuda a descrever o que vemos sem confundir aparência com composição.","explanation":"Mistura é formada por dois ou mais materiais. Para a classificação escolar, observe quantas fases visíveis compõem o sistema: uma fase uniforme indica mistura homogênea; duas ou mais fases visíveis indicam mistura heterogênea. Dissolver sal em água não significa que o sal desapareceu como matéria: suas partículas continuam distribuídas no líquido. A observação depende das condições e do tempo; registre o que foi realmente observado.","workedExample":{"prompt":"Após mexer água e areia, o sistema tem uma ou mais fases visíveis?","steps":["Observe o líquido sem agitar novamente.","A areia pode se depositar e continuar distinguível da água.","Como há regiões com aspecto diferente, observam-se duas fases.","Classifique o sistema como heterogêneo."],"answer":"Mistura heterogênea."},"guidedPractice":[{"prompt":"Compare um copo com água e sal dissolvido a outro com água e óleo.","scaffold":"Conte as fases visíveis em cada sistema, sem usar somente a cor."},{"prompt":"Explique por que água com sal continua sendo uma mistura.","scaffold":"Pense nos materiais usados antes de mexer."},{"prompt":"O que precisa ser registrado para outra pessoa repetir a observação?","scaffold":"Inclua materiais, quantidades aproximadas e o que foi visto."}],"application":[{"context":"Laboratório escolar","prompt":"Uma amostra contém água e pequenos grãos de areia. Registre evidências observáveis e classifique a mistura."},{"context":"Cozinha","prompt":"Açúcar foi misturado à água até não ser mais visível. Explique a classificação e o que a observação não permite concluir."}],"review":["Mistura reúne dois ou mais materiais.","Fase é cada porção visualmente uniforme do sistema observado.","Uma fase visível indica mistura homogênea; mais de uma, heterogênea.","Dissolução não significa desaparecimento da matéria.","Descreva evidências antes de classificar."],"learningCheck":{"passRule":"A revisão técnica verifica cada resposta; a revisão pedagógica humana permanece pendente.","questionIds":["cev2-ef06ci01-q1","cev2-ef06ci01-q2","cev2-ef06ci01-q3","cev2-ef06ci01-q4","cev2-ef06ci01-q5"]}},"questions":[{"id":"cev2-ef06ci01-q1","purpose":"PROBE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Depois de mexer água com sal até o sal não ficar visível, o sistema observado apresenta:","options":["Uma fase visível e aspecto uniforme","Duas camadas visíveis","Somente sal sólido","Três fases obrigatórias"],"correctAnswer":"Uma fase visível e aspecto uniforme","explanation":"Quando o sal está dissolvido e distribuído, observa-se uma fase uniforme; a mistura continua contendo os dois materiais.","misconception":"Concluir que o sal deixou de existir porque não pode ser visto.","officialSkillCode":"EF06CI01"},{"id":"cev2-ef06ci01-q2","purpose":"PRACTICE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Água e óleo, em repouso, formam camadas visíveis. Como classificar?","options":["Heterogênea","Homogênea","Substância pura","Gás"],"correctAnswer":"Heterogênea","explanation":"As duas camadas são fases distintas e visíveis, evidência de mistura heterogênea.","misconception":"Classificar pela quantidade de líquidos, sem observar fases.","officialSkillCode":"EF06CI01"},{"id":"cev2-ef06ci01-q3","purpose":"TRANSFER","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Uma estudante mistura água, sal e areia. A areia se deposita no fundo; a água salgada permanece acima. O sistema é:","options":["Heterogêneo, pois há mais de uma fase visível","Homogêneo, pois todos os materiais foram mexidos","Substância pura, pois a areia ficou no fundo","Homogêneo, porque o sal não aparece"],"correctAnswer":"Heterogêneo, pois há mais de uma fase visível","explanation":"A porção de areia e a solução aquosa podem ser distinguidas como fases diferentes.","misconception":"Considerar apenas o sal dissolvido e ignorar a areia.","officialSkillCode":"EF06CI01"},{"id":"cev2-ef06ci01-q4","purpose":"LOCK_IN","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Qual observação é evidência mais direta para classificar uma mistura como heterogênea?","options":["É possível distinguir duas porções com aspectos diferentes","O recipiente é transparente","Os materiais foram comprados em lugares diferentes","A mistura foi agitada por dez segundos"],"correctAnswer":"É possível distinguir duas porções com aspectos diferentes","explanation":"A classificação se apoia nas fases observáveis do sistema.","misconception":"Usar informação sobre o recipiente ou o procedimento como se fosse a observação das fases.","officialSkillCode":"EF06CI01"},{"id":"cev2-ef06ci01-q5","purpose":"REVIEW","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Ao não ver mais os cristais de açúcar após mexer a água, o que é correto concluir?","options":["O açúcar se dissolveu e a mistura pode apresentar uma fase uniforme","O açúcar foi destruído","A água virou substância pura","Não há mais matéria no copo"],"correctAnswer":"O açúcar se dissolveu e a mistura pode apresentar uma fase uniforme","explanation":"A aparência uniforme é compatível com dissolução; a matéria do açúcar continua na solução.","misconception":"Confundir invisibilidade com desaparecimento.","officialSkillCode":"EF06CI01"}],"version":"central-estudos-v2-candidate-2026-10-25.2","stage":"ENSINO_FUNDAMENTAL","contentAuthoringStatus":"TECH_VALIDATED_PENDING_REVIEW","pedagogicalReviewStatus":"PEDAGOGICAL_REVIEW_PENDING","publicationStatus":"STAGING","officialSource":{"id":"BNCC_EI_EF_2018","documentVersion":"BNCC Educação Infantil e Ensino Fundamental, versão final 2018","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","catalogPath":"content/bncc/official/catalog-2018.json","repositoryExtractionStatus":"AUTOMATED_TEXT_EXTRACTION_REVIEW_REQUIRED"}}'::jsonb),
  ('CEV2_EF06CI02_TRANSFORMACOES_01', 'central-estudos-v2-candidate-2026-10-25.2', 'SCIENCE', 6, 'EF06CI02', '9a4d01c1d90930b19bfa02129a04d0cb23c2fb8cc822e61103299def4b71ceb5', '{"journeyCode":"CEV2_EF06CI02_TRANSFORMACOES_01","journeyTitle":"Evidências de transformações químicas","subject":"SCIENCE","grade":6,"officialSkillCode":"EF06CI02","skill":"SCIENCE_CHEMICAL_TRANSFORMATION_EVIDENCE","unitCode":"SCI_MATERIAIS","unitTitle":"Materiais e transformações","officialText":"Identificar evidências de transformações químicas a partir do resultado de misturas de materiais que originam produtos diferentes dos que foram misturados.","lesson":{"title":"Distinguir mistura de transformação química","estimatedMinutes":19,"introduction":"Misturar farinha e água muda a aparência, mas nem toda mudança visível produz novas substâncias. Em algumas combinações, aparecem gás, mudança de cor ou materiais com propriedades diferentes. O importante é reunir evidências, não adivinhar apenas pelo aspecto.","explanation":"Uma transformação química ocorre quando materiais de partida dão origem a substâncias com propriedades diferentes. Formação de gás, mudança persistente de cor, liberação ou absorção de energia e formação de sólido podem ser indícios, mas cada sinal precisa ser interpretado no contexto. Misturar sem reagir também pode mudar a aparência. Em experimentos escolares, compare o antes e o depois e siga as regras de segurança; nunca prove ou cheire diretamente materiais.","workedExample":{"prompt":"Vinagre e bicarbonato são misturados e surgem bolhas. Qual evidência deve ser registrada?","steps":["Registre os materiais antes da mistura.","Observe a formação de bolhas sem aproximar o rosto.","Bolhas sugerem a produção de um gás durante a reação.","Relacione o sinal ao conjunto de mudanças, sem afirmar além do observado."],"answer":"A formação de gás é evidência compatível com transformação química."},"guidedPractice":[{"prompt":"Compare gelo derretendo com massa de bolo assando.","scaffold":"Pergunte se surgem materiais com propriedades diferentes e se a mudança pode ser desfeita facilmente."},{"prompt":"Quais observações podem ser registradas sem tocar nos materiais?","scaffold":"Cor, bolhas, temperatura medida e formação de sólido podem ser descritos."},{"prompt":"Por que uma mudança de cor isolada não prova sempre uma reação?","scaffold":"Pense em iluminação, mistura de tintas e outras mudanças físicas."}],"application":[{"context":"Cozinha","prompt":"Ao assar uma massa, cor e textura mudam. Cite evidências e explique por que a conclusão deve considerar o conjunto da transformação."},{"context":"Experimento seguro","prompt":"Planeje um registro de observação para vinagre e bicarbonato, indicando o que observar antes e depois e como manter segurança."}],"review":["Mudança de aparência, sozinha, não prova transformação química.","Compare materiais antes e produtos depois.","Gás, cor, temperatura ou sólido podem ser evidências, conforme o contexto.","Registre somente o que foi observado.","Siga instruções de segurança e não prove materiais."],"learningCheck":{"passRule":"A revisão técnica verifica cada resposta; a revisão pedagógica humana permanece pendente.","questionIds":["cev2-ef06ci02-q1","cev2-ef06ci02-q2","cev2-ef06ci02-q3","cev2-ef06ci02-q4","cev2-ef06ci02-q5"]}},"questions":[{"id":"cev2-ef06ci02-q1","purpose":"PROBE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Ao misturar vinagre e bicarbonato, observam-se bolhas. Qual é uma interpretação cuidadosa?","options":["A formação de gás é evidência compatível com transformação química","As bolhas provam que o vinagre evaporou por completo","A mistura virou uma substância pura","Não ocorreu mudança porque os materiais continuam no copo"],"correctAnswer":"A formação de gás é evidência compatível com transformação química","explanation":"As bolhas são uma evidência observável de formação de gás; a explicação considera o processo da mistura.","misconception":"Afirmar que as bolhas, sem contexto, provam qualquer conclusão específica.","officialSkillCode":"EF06CI02"},{"id":"cev2-ef06ci02-q2","purpose":"PRACTICE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Qual situação apresenta a evidência mais clara de novos produtos após misturar materiais?","options":["Vinagre e bicarbonato liberam gás","Areia é colocada em água e se deposita","Pedras são separadas por tamanho","Água líquida é colocada em outro copo"],"correctAnswer":"Vinagre e bicarbonato liberam gás","explanation":"A liberação de gás na reação entre os materiais é evidência de transformação química.","misconception":"Confundir separação física ou transferência de recipiente com formação de substância.","officialSkillCode":"EF06CI02"},{"id":"cev2-ef06ci02-q3","purpose":"TRANSFER","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Uma fruta cortada escurece depois de algum tempo. O que um registro científico deve fazer primeiro?","options":["Descrever a mudança observada e comparar condições antes de explicar","Afirmar que toda mudança de cor é uma nova substância","Misturar a fruta com qualquer produto de limpeza","Provar a fruta para identificar a reação"],"correctAnswer":"Descrever a mudança observada e comparar condições antes de explicar","explanation":"Registrar a observação e as condições permite avaliar a evidência sem tirar conclusões precipitadas.","misconception":"Tratar uma evidência isolada como prova completa ou propor ação insegura.","officialSkillCode":"EF06CI02"},{"id":"cev2-ef06ci02-q4","purpose":"LOCK_IN","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Qual exemplo é principalmente uma mudança física?","options":["Gelo derrete e continua sendo água","Pão assa e muda de cheiro e textura","Vinagre e bicarbonato liberam gás","Ferro enferruja ao longo do tempo"],"correctAnswer":"Gelo derrete e continua sendo água","explanation":"Na fusão, muda o estado físico, mas o material continua sendo água.","misconception":"Supor que toda mudança visível é uma reação química.","officialSkillCode":"EF06CI02"},{"id":"cev2-ef06ci02-q5","purpose":"REVIEW","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Durante uma observação escolar, qual atitude é segura e cientificamente útil?","options":["Registrar mudanças sem provar nem cheirar diretamente os materiais","Aproximar o rosto para sentir qualquer gás","Misturar produtos de limpeza para comparar","Descartar o registro e confiar apenas na memória"],"correctAnswer":"Registrar mudanças sem provar nem cheirar diretamente os materiais","explanation":"Observação documentada e segura permite comparar o antes e o depois.","misconception":"Priorizar curiosidade sem seguir as regras de segurança.","officialSkillCode":"EF06CI02"}],"version":"central-estudos-v2-candidate-2026-10-25.2","stage":"ENSINO_FUNDAMENTAL","contentAuthoringStatus":"TECH_VALIDATED_PENDING_REVIEW","pedagogicalReviewStatus":"PEDAGOGICAL_REVIEW_PENDING","publicationStatus":"STAGING","officialSource":{"id":"BNCC_EI_EF_2018","documentVersion":"BNCC Educação Infantil e Ensino Fundamental, versão final 2018","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","catalogPath":"content/bncc/official/catalog-2018.json","repositoryExtractionStatus":"AUTOMATED_TEXT_EXTRACTION_REVIEW_REQUIRED"}}'::jsonb),
  ('CEV2_EF06CI03_SEPARACAO_01', 'central-estudos-v2-candidate-2026-10-25.2', 'SCIENCE', 6, 'EF06CI03', '522c556d8bd9be577af6a643feb788f007042c75920793cd9aec80d8844e5686', '{"journeyCode":"CEV2_EF06CI03_SEPARACAO_01","journeyTitle":"Escolher métodos de separação","subject":"SCIENCE","grade":6,"officialSkillCode":"EF06CI03","skill":"SCIENCE_SEPARATION_METHODS","unitCode":"SCI_MATERIAIS","unitTitle":"Materiais e transformações","officialText":"Selecionar métodos mais adequados para a separação de diferentes sistemas heterogêneos a partir da identificação de processos de separação de materiais.","lesson":{"title":"Relacionar propriedades e métodos de separação","estimatedMinutes":20,"introduction":"Uma mistura de areia e água precisa ser separada. O método escolhido depende do que sabemos dos materiais: tamanho das partículas, capacidade de dissolver, densidade e possibilidade de evaporação.","explanation":"Sistemas heterogêneos podem ser separados por métodos físicos escolhidos conforme as propriedades dos componentes. Filtração retém partículas sólidas maiores que os poros do filtro; decantação aproveita a diferença de densidade depois que as fases se separam; peneiração distingue sólidos por tamanho; evaporação pode recuperar um sólido dissolvido, embora a água não seja recolhida nesse processo simples. Um método adequado responde ao objetivo e considera segurança e impacto ambiental.","workedExample":{"prompt":"Como separar areia de água em uma atividade escolar?","steps":["A areia não está dissolvida e forma partículas sólidas.","Um filtro permite a passagem da água e retém grande parte da areia.","A filtração é adequada para separar sólido não dissolvido de líquido.","Registre que a água filtrada pode ainda conter substâncias dissolvidas."],"answer":"Filtração, observando que ela não remove substâncias dissolvidas."},"guidedPractice":[{"prompt":"Escolha entre peneiração, filtração e decantação para separar cada mistura.","scaffold":"Observe se são sólidos de tamanhos diferentes ou sólido e líquido."},{"prompt":"Como recuperar sal dissolvido em água usando evaporação?","scaffold":"A água passa ao estado gasoso e o sal pode permanecer como sólido."},{"prompt":"O que deve ser considerado ao escolher um método para grande escala?","scaffold":"Além de separar, avalie energia, resíduos, segurança e recuperação dos materiais."}],"application":[{"context":"Tratamento de água","prompt":"Explique por que uma peneira grossa não remove sal dissolvido e proponha um processo diferente para reter partículas maiores."},{"context":"Reciclagem","prompt":"Uma mistura tem parafusos de ferro e areia. Escolha um método, justifique pela propriedade usada e indique um limite."}],"review":["Identifique os componentes e se há uma ou mais fases.","Relacione o método à propriedade física usada.","Filtração retém sólidos não dissolvidos; decantação separa fases após repouso.","Evaporação pode deixar o sólido dissolvido, mas não recolhe a água.","Considere finalidade, segurança e resíduos."],"learningCheck":{"passRule":"A revisão técnica verifica cada resposta; a revisão pedagógica humana permanece pendente.","questionIds":["cev2-ef06ci03-q1","cev2-ef06ci03-q2","cev2-ef06ci03-q3","cev2-ef06ci03-q4","cev2-ef06ci03-q5"]}},"questions":[{"id":"cev2-ef06ci03-q1","purpose":"PROBE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Qual método separa melhor areia não dissolvida da água em uma atividade simples?","options":["Filtração","Peneiração fina do líquido sem filtro","Imantação","Congelamento"],"correctAnswer":"Filtração","explanation":"O filtro retém partículas de areia e permite a passagem da água.","misconception":"Achar que a água com areia pode ser separada por magnetismo.","officialSkillCode":"EF06CI03"},{"id":"cev2-ef06ci03-q2","purpose":"PRACTICE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Para separar pedrinhas de tamanhos diferentes, qual método é mais adequado?","options":["Peneiração","Evaporação","Destilação do sólido","Dissolução em óleo"],"correctAnswer":"Peneiração","explanation":"A peneira separa sólidos conforme o tamanho de suas partículas.","misconception":"Escolher método de separação de sólido e líquido para dois sólidos.","officialSkillCode":"EF06CI03"},{"id":"cev2-ef06ci03-q3","purpose":"TRANSFER","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Depois que água e óleo ficam em camadas, qual processo pode facilitar a separação?","options":["Decantação","Filtração para dissolver o óleo","Peneiração","Evaporação do óleo sem avaliar segurança"],"correctAnswer":"Decantação","explanation":"As fases líquidas com densidades diferentes podem ser separadas por decantação apropriada.","misconception":"Supor que filtros comuns retêm um líquido dissolvido em outro.","officialSkillCode":"EF06CI03"},{"id":"cev2-ef06ci03-q4","purpose":"LOCK_IN","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Uma solução de água e sal é filtrada. O que se espera?","options":["O sal dissolvido atravessa o filtro junto com a água","Todo o sal fica retido no filtro","A água vira areia","O sal se transforma em gás imediatamente"],"correctAnswer":"O sal dissolvido atravessa o filtro junto com a água","explanation":"Partículas dissolvidas passam pelo filtro comum; filtração não separa uma solução desse modo.","misconception":"Confundir substância dissolvida com sólido suspenso.","officialSkillCode":"EF06CI03"},{"id":"cev2-ef06ci03-q5","purpose":"REVIEW","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Para obter sal de uma solução aquosa por evaporação simples, o que fica no recipiente ao final?","options":["O sal sólido","A água líquida e todo o sal, sem mudança","Somente o filtro","Areia formada pela água"],"correctAnswer":"O sal sólido","explanation":"A água evapora e o soluto não volátil pode permanecer como sólido.","misconception":"Esperar que evaporação simples recupere também a água como líquido.","officialSkillCode":"EF06CI03"}],"version":"central-estudos-v2-candidate-2026-10-25.2","stage":"ENSINO_FUNDAMENTAL","contentAuthoringStatus":"TECH_VALIDATED_PENDING_REVIEW","pedagogicalReviewStatus":"PEDAGOGICAL_REVIEW_PENDING","publicationStatus":"STAGING","officialSource":{"id":"BNCC_EI_EF_2018","documentVersion":"BNCC Educação Infantil e Ensino Fundamental, versão final 2018","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","catalogPath":"content/bncc/official/catalog-2018.json","repositoryExtractionStatus":"AUTOMATED_TEXT_EXTRACTION_REVIEW_REQUIRED"}}'::jsonb),
  ('CEV2_EF06LP02_NOTICIA_01', 'central-estudos-v2-candidate-2026-10-25.2', 'PORTUGUESE', 6, 'EF06LP02', '8a28f732297eb146773df2255f8fc45cec3097efa322ed564e694f7384fe258d', '{"journeyCode":"CEV2_EF06LP02_NOTICIA_01","journeyTitle":"Notícia e outros gêneros jornalísticos","subject":"PORTUGUESE","grade":6,"officialSkillCode":"EF06LP02","skill":"PORTUGUESE_JOURNALISTIC_GENRES","unitCode":"LP_LEITURA","unitTitle":"Leitura, gêneros e sentidos","officialText":"Estabelecer relação entre os diferentes gêneros jornalísticos, compreendendo a centralidade da notícia.","lesson":{"title":"Reconhecer a notícia e sua relação com outros gêneros","estimatedMinutes":20,"introduction":"Uma escola publica uma notícia sobre a abertura da biblioteca e, na semana seguinte, uma entrevista com estudantes sobre o espaço. Os textos tratam do mesmo assunto, mas têm objetivos e formas diferentes.","explanation":"Gêneros jornalísticos compartilham a circulação de informações de interesse público, mas organizam o conteúdo de modos diferentes. A notícia apresenta um fato de forma concisa, geralmente respondendo o que aconteceu, com quem, onde e quando. Reportagens podem aprofundar causas, dados e diferentes perspectivas; entrevistas organizam perguntas e respostas. Manchete, título, data, autoria e fontes ajudam o leitor a compreender a publicação, mas não substituem a leitura do texto completo.","workedExample":{"prompt":"“Biblioteca da escola reabre nesta segunda-feira” é uma manchete. O que ela informa e o que ainda precisa ser confirmado no texto?","steps":["A manchete indica o acontecimento principal: a reabertura.","“Nesta segunda-feira” apresenta uma referência temporal que depende da data da publicação.","O texto deve trazer informações como local, horário e fonte.","A manchete resume; ela não apresenta necessariamente todos os detalhes."],"answer":"A manchete anuncia a reabertura, mas o leitor deve conferir data, local e detalhes na notícia."},"guidedPractice":[{"prompt":"Compare uma notícia curta e uma entrevista sobre o mesmo evento.","scaffold":"Observe quem organiza a informação e qual pergunta cada gênero responde."},{"prompt":"Que dados ajudam a verificar quando e onde um fato ocorreu?","scaffold":"Procure data, local, autoria e fontes citadas."},{"prompt":"Por que a manchete não basta para conhecer todos os lados de um fato?","scaffold":"Ela seleciona e resume informações em poucas palavras."}],"application":[{"context":"Comunicação escolar","prompt":"Planeje uma notícia curta sobre uma feira de ciências. Liste as informações essenciais e indique como confirmaria cada uma."},{"context":"Leitura crítica","prompt":"Uma manchete chama atenção para um detalhe, mas o texto destaca outro. Explique por que é importante ler o corpo da notícia."}],"review":["A notícia relata um fato de interesse público de modo conciso.","Reportagem pode aprofundar contexto, fontes e perspectivas.","Entrevista organiza perguntas e respostas.","Manchete resume e seleciona; o texto oferece detalhes.","Confira autoria, data e fontes antes de compartilhar."],"learningCheck":{"passRule":"A revisão técnica verifica cada resposta; a revisão pedagógica humana permanece pendente.","questionIds":["cev2-ef06lp02-q1","cev2-ef06lp02-q2","cev2-ef06lp02-q3","cev2-ef06lp02-q4","cev2-ef06lp02-q5"]}},"questions":[{"id":"cev2-ef06lp02-q1","purpose":"PROBE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Qual é uma função central de uma notícia?","options":["Relatar um fato de interesse público com informações essenciais","Ensinar uma receita passo a passo","Contar sempre uma história imaginária","Apresentar somente a opinião pessoal do leitor"],"correctAnswer":"Relatar um fato de interesse público com informações essenciais","explanation":"A notícia informa um fato e ajuda o leitor a localizar dados principais.","misconception":"Confundir notícia com narrativa ficcional ou opinião individual.","officialSkillCode":"EF06LP02"},{"id":"cev2-ef06lp02-q2","purpose":"PRACTICE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Em uma entrevista, como costuma ser organizado o texto?","options":["Por perguntas e respostas","Somente por versos rimados","Por lista de ingredientes","Por instruções numeradas obrigatórias"],"correctAnswer":"Por perguntas e respostas","explanation":"A entrevista registra perguntas do entrevistador e respostas da pessoa entrevistada.","misconception":"Reduzir todo texto jornalístico à forma de uma notícia.","officialSkillCode":"EF06LP02"},{"id":"cev2-ef06lp02-q3","purpose":"TRANSFER","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Uma reportagem traz dados, entrevista moradores e explica como uma praça mudou ao longo do tempo. O que a diferencia de uma notícia breve?","options":["Aprofunda o contexto e diferentes informações sobre o tema","Não pode informar fatos","É sempre uma conversa privada","Dispensa fontes e autoria"],"correctAnswer":"Aprofunda o contexto e diferentes informações sobre o tema","explanation":"A reportagem desenvolve o assunto com contexto, dados e fontes, enquanto a notícia tende a ser mais concisa.","misconception":"Supor que a reportagem deixa de ser jornalística por ser mais detalhada.","officialSkillCode":"EF06LP02"},{"id":"cev2-ef06lp02-q4","purpose":"LOCK_IN","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Uma manchete informa “Aulas de música começam na quinta”, mas não diz o horário. Onde procurar esse detalhe?","options":["No texto completo e nas informações de serviço da publicação","Concluir que todas as aulas serão à meia-noite","Somente no tamanho da manchete","Ignorar a data da publicação"],"correctAnswer":"No texto completo e nas informações de serviço da publicação","explanation":"A manchete resume o fato; detalhes devem ser conferidos no corpo e no serviço da notícia.","misconception":"Achar que manchetes sempre trazem todas as informações.","officialSkillCode":"EF06LP02"},{"id":"cev2-ef06lp02-q5","purpose":"REVIEW","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Dois textos tratam do mesmo acontecimento: um relata o fato e outro apresenta respostas de uma atleta. Como podem ser classificados?","options":["Notícia e entrevista, respectivamente","Dois anúncios necessariamente","Conto e receita","Bilhete e verbete"],"correctAnswer":"Notícia e entrevista, respectivamente","explanation":"O primeiro relata o acontecimento; o segundo organiza a fala da atleta por perguntas e respostas.","misconception":"Classificar os gêneros apenas pelo tema, sem observar organização e finalidade.","officialSkillCode":"EF06LP02"}],"version":"central-estudos-v2-candidate-2026-10-25.2","stage":"ENSINO_FUNDAMENTAL","contentAuthoringStatus":"TECH_VALIDATED_PENDING_REVIEW","pedagogicalReviewStatus":"PEDAGOGICAL_REVIEW_PENDING","publicationStatus":"STAGING","officialSource":{"id":"BNCC_EI_EF_2018","documentVersion":"BNCC Educação Infantil e Ensino Fundamental, versão final 2018","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","catalogPath":"content/bncc/official/catalog-2018.json","repositoryExtractionStatus":"AUTOMATED_TEXT_EXTRACTION_REVIEW_REQUIRED"}}'::jsonb),
  ('CEV2_EF06LP03_SERIE_SINONIMICA_01', 'central-estudos-v2-candidate-2026-10-25.2', 'PORTUGUESE', 6, 'EF06LP03', 'df240d5f6469043404813a2b90bf957afa93e826972012d32316b43eb5bdea47', '{"journeyCode":"CEV2_EF06LP03_SERIE_SINONIMICA_01","journeyTitle":"Escolha de palavras e sentidos","subject":"PORTUGUESE","grade":6,"officialSkillCode":"EF06LP03","skill":"PORTUGUESE_SYNONYMY_CONTEXT","unitCode":"LP_LEITURA","unitTitle":"Leitura, gêneros e sentidos","officialText":"Analisar diferenças de sentido entre palavras de uma série sinonímica.","lesson":{"title":"Sinônimos dependem do contexto","estimatedMinutes":18,"introduction":"Em um aviso, “a entrada está liberada” pode ser adequada; em outro contexto, “a entrada está gratuita” significa algo diferente. Palavras próximas nem sempre podem ser trocadas sem mudar o sentido.","explanation":"Palavras de uma série sinonímica compartilham alguns sentidos, mas podem variar em intensidade, formalidade, avaliação e combinações comuns. “Observar” e “examinar” se aproximam, mas examinar costuma indicar atenção mais detalhada. Para escolher, releia a frase, identifique o que o autor quer dizer e teste a substituição. Se a ideia, o tom ou a precisão mudarem, as palavras não funcionam como equivalentes naquele contexto.","workedExample":{"prompt":"No trecho “A pesquisadora examinou as amostras ao microscópio”, qual troca preserva melhor a ideia?","steps":["Identifique a ação: observar as amostras com atenção.","“Analisou” mantém a ideia de observação cuidadosa.","“Olhou” é possível, mas menos específico.","Confira se a frase continua adequada ao contexto científico."],"answer":"“Analisou” preserva o sentido com maior precisão."},"guidedPractice":[{"prompt":"Compare “casa”, “moradia” e “lar” em frases diferentes.","scaffold":"Perceba diferenças de formalidade e de vínculo afetivo."},{"prompt":"Substitua “disse” por “avisou” em uma frase e avalie o que muda.","scaffold":"Pergunte se a fala comunica uma informação importante a alguém."},{"prompt":"Por que um dicionário de sinônimos oferece possibilidades, não trocas automáticas?","scaffold":"Considere regência, situação e intenção do texto."}],"application":[{"context":"Revisão de texto","prompt":"Revise a frase “O estudante viu os dados com cuidado”. Escolha um verbo mais preciso e explique a diferença."},{"context":"Comunicação","prompt":"Em um convite formal, compare “venha”, “compareça” e “apareça”. Qual combina melhor com o tom? Justifique."}],"review":["Sinônimos têm sentidos próximos, não necessariamente idênticos.","Contexto, formalidade e intensidade influenciam a escolha.","Teste a substituição dentro da frase.","Observe se a precisão e o tom são preservados.","Use o dicionário como apoio e confirme pelo contexto."],"learningCheck":{"passRule":"A revisão técnica verifica cada resposta; a revisão pedagógica humana permanece pendente.","questionIds":["cev2-ef06lp03-q1","cev2-ef06lp03-q2","cev2-ef06lp03-q3","cev2-ef06lp03-q4","cev2-ef06lp03-q5"]}},"questions":[{"id":"cev2-ef06lp03-q1","purpose":"PROBE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Na frase “A turma observou atentamente o mapa”, qual verbo mantém melhor a ideia de olhar com atenção?","options":["Examinou","Esqueceu","Escondeu","Anunciou"],"correctAnswer":"Examinou","explanation":"“Examinou” mantém a ideia de observar cuidadosamente o mapa.","misconception":"Escolher palavra que compartilha alguma situação, mas não o sentido da ação.","officialSkillCode":"EF06LP03"},{"id":"cev2-ef06lp03-q2","purpose":"PRACTICE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Em “O aviso informa que a biblioteca fecha às 17h”, qual palavra pode substituir “informa” sem mudar muito o sentido?","options":["Comunica","Esconde","Apaga","Atrasa"],"correctAnswer":"Comunica","explanation":"“Comunica” também indica transmitir uma informação ao leitor.","misconception":"Usar palavra com sentido oposto ou referente a outra ação.","officialSkillCode":"EF06LP03"},{"id":"cev2-ef06lp03-q3","purpose":"TRANSFER","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Em um convite formal, “compareça à reunião” soa mais adequado que “dê as caras”. Por quê?","options":["As expressões têm níveis de formalidade diferentes","As duas têm sempre o mesmo tom","“Compareça” não tem relação com ir a um lugar","A frase formal precisa rimar"],"correctAnswer":"As expressões têm níveis de formalidade diferentes","explanation":"O contexto formal favorece uma escolha compatível com o tom esperado.","misconception":"Ignorar o efeito de registro e considerar só o sentido geral de presença.","officialSkillCode":"EF06LP03"},{"id":"cev2-ef06lp03-q4","purpose":"LOCK_IN","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Na frase “O atleta correu rapidamente”, substituir “rapidamente” por “devagar” preserva o sentido?","options":["Não; “devagar” indica o sentido contrário","Sim; as palavras são sinônimas perfeitas","Sim; ambas indicam rapidez","Não, porque advérbios não podem ser substituídos"],"correctAnswer":"Não; “devagar” indica o sentido contrário","explanation":"A substituição altera a informação sobre a velocidade da ação.","misconception":"Confundir pertencimento à mesma classe gramatical com sinonímia.","officialSkillCode":"EF06LP03"},{"id":"cev2-ef06lp03-q5","purpose":"REVIEW","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Qual é a melhor maneira de verificar se um sinônimo funciona em uma frase?","options":["Substituir no contexto e conferir se ideia, precisão e tom permanecem","Escolher sempre a palavra mais longa","Usar a primeira opção encontrada","Trocar todas as palavras por termos formais"],"correctAnswer":"Substituir no contexto e conferir se ideia, precisão e tom permanecem","explanation":"A leitura contextual revela mudanças de sentido, intensidade ou registro.","misconception":"Tratar a lista de sinônimos como equivalência automática.","officialSkillCode":"EF06LP03"}],"version":"central-estudos-v2-candidate-2026-10-25.2","stage":"ENSINO_FUNDAMENTAL","contentAuthoringStatus":"TECH_VALIDATED_PENDING_REVIEW","pedagogicalReviewStatus":"PEDAGOGICAL_REVIEW_PENDING","publicationStatus":"STAGING","officialSource":{"id":"BNCC_EI_EF_2018","documentVersion":"BNCC Educação Infantil e Ensino Fundamental, versão final 2018","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","catalogPath":"content/bncc/official/catalog-2018.json","repositoryExtractionStatus":"AUTOMATED_TEXT_EXTRACTION_REVIEW_REQUIRED"}}'::jsonb),
  ('CEV2_EF06LP05_MODOS_VERBAIS_01', 'central-estudos-v2-candidate-2026-10-25.2', 'PORTUGUESE', 6, 'EF06LP05', '92b3094aa8496ec3289713401a59ea4a6d3db95dee4a1a821ba85f6a888ce30c', '{"journeyCode":"CEV2_EF06LP05_MODOS_VERBAIS_01","journeyTitle":"Modos verbais e intenção comunicativa","subject":"PORTUGUESE","grade":6,"officialSkillCode":"EF06LP05","skill":"PORTUGUESE_VERB_MOOD_EFFECTS","unitCode":"LP_LEITURA","unitTitle":"Leitura, gêneros e sentidos","officialText":"Identificar os efeitos de sentido dos modos verbais, considerando o gênero textual e a intenção comunicativa.","lesson":{"title":"O modo verbal ajuda a orientar o leitor","estimatedMinutes":19,"introduction":"Compare “A feira começa às nove”, “Talvez a feira comece às nove” e “Chegue às nove”. Os verbos apresentam uma informação, uma possibilidade e uma orientação.","explanation":"O modo indicativo costuma apresentar fatos ou afirmações; o subjuntivo marca possibilidade, hipótese ou desejo; o imperativo orienta, solicita ou aconselha. O efeito depende do gênero e da situação: em uma notícia, a forma verbal pode apresentar um fato; em uma regra, pode orientar uma ação. Leia a frase completa e observe quem fala, para quem e com qual finalidade antes de classificar o efeito.","workedExample":{"prompt":"Em “Talvez a equipe chegue antes do início”, que efeito o verbo produz?","steps":["“Talvez” introduz uma possibilidade, não uma certeza.","“Chegue” está no modo subjuntivo.","O enunciado expressa expectativa incerta.","Compare com “A equipe chega às oito”, que apresenta uma afirmação."],"answer":"A frase expressa uma possibilidade."},"guidedPractice":[{"prompt":"Compare “Use o cinto” e “Você usa o cinto”.","scaffold":"Observe qual frase orienta uma ação."},{"prompt":"Transforme uma certeza em hipótese usando “talvez”.","scaffold":"A escolha do modo verbal deve acompanhar o sentido de possibilidade."},{"prompt":"Por que uma instrução pode usar o imperativo sem ser agressiva?","scaffold":"O gênero e a cortesia do texto também influenciam o efeito."}],"application":[{"context":"Cartaz escolar","prompt":"Escreva uma orientação para cuidar dos livros e explique o efeito do verbo escolhido."},{"context":"Notícia","prompt":"Compare “O grêmio organiza a feira” com “O grêmio talvez organize a feira”. Explique a diferença de certeza."}],"review":["Indicativo costuma afirmar ou apresentar fatos.","Subjuntivo pode expressar dúvida, possibilidade, desejo ou hipótese.","Imperativo orienta, solicita ou aconselha.","O efeito depende do gênero, do interlocutor e da intenção.","Leia o contexto antes de interpretar o verbo."],"learningCheck":{"passRule":"A revisão técnica verifica cada resposta; a revisão pedagógica humana permanece pendente.","questionIds":["cev2-ef06lp05-q1","cev2-ef06lp05-q2","cev2-ef06lp05-q3","cev2-ef06lp05-q4","cev2-ef06lp05-q5"]}},"questions":[{"id":"cev2-ef06lp05-q1","purpose":"PROBE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Na frase “Talvez a biblioteca abra no sábado”, o verbo “abra” indica:","options":["Possibilidade","Ordem direta","Fato confirmado","Ação encerrada"],"correctAnswer":"Possibilidade","explanation":"“Talvez” e o subjuntivo apresentam uma hipótese, não uma confirmação.","misconception":"Ler qualquer verbo no presente como certeza.","officialSkillCode":"EF06LP05"},{"id":"cev2-ef06lp05-q2","purpose":"PRACTICE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Em um cartaz, “Separe o papel para reciclagem” tem principalmente o efeito de:","options":["Orientar uma ação","Relatar um fato passado","Expressar dúvida","Descrever uma lembrança"],"correctAnswer":"Orientar uma ação","explanation":"O imperativo “separe” dirige uma orientação ao leitor.","misconception":"Confundir uma orientação com uma afirmação sobre o que já aconteceu.","officialSkillCode":"EF06LP05"},{"id":"cev2-ef06lp05-q3","purpose":"TRANSFER","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Qual frase apresenta uma informação como fato, sem marcar hipótese?","options":["A equipe começa a apresentação às dez","Talvez a equipe comece às dez","Se a equipe começasse às dez","Comece a apresentação às dez"],"correctAnswer":"A equipe começa a apresentação às dez","explanation":"A frase no indicativo apresenta diretamente a informação.","misconception":"Ignorar marcadores de hipótese ou interpretar uma ordem como notícia.","officialSkillCode":"EF06LP05"},{"id":"cev2-ef06lp05-q4","purpose":"LOCK_IN","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Em “Espero que os estudantes participem”, qual sentido o subjuntivo ajuda a expressar?","options":["Desejo ou expectativa","Ordem concluída","Fato comprovado","Ação habitual obrigatória"],"correctAnswer":"Desejo ou expectativa","explanation":"“Espero que” introduz desejo ou expectativa e favorece o subjuntivo “participem”.","misconception":"Classificar o modo verbal sem observar a expressão que o acompanha.","officialSkillCode":"EF06LP05"},{"id":"cev2-ef06lp05-q5","purpose":"REVIEW","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Por que “Feche a janela” pode ser uma instrução em um manual?","options":["O imperativo orienta o leitor a realizar uma ação","O verbo sempre relata algo passado","A frase expressa uma possibilidade incerta","Todo imperativo é necessariamente uma ameaça"],"correctAnswer":"O imperativo orienta o leitor a realizar uma ação","explanation":"O gênero manual e o contexto mostram que o imperativo organiza passos.","misconception":"Atribuir um tom agressivo automático sem considerar gênero e finalidade.","officialSkillCode":"EF06LP05"}],"version":"central-estudos-v2-candidate-2026-10-25.2","stage":"ENSINO_FUNDAMENTAL","contentAuthoringStatus":"TECH_VALIDATED_PENDING_REVIEW","pedagogicalReviewStatus":"PEDAGOGICAL_REVIEW_PENDING","publicationStatus":"STAGING","officialSource":{"id":"BNCC_EI_EF_2018","documentVersion":"BNCC Educação Infantil e Ensino Fundamental, versão final 2018","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","catalogPath":"content/bncc/official/catalog-2018.json","repositoryExtractionStatus":"AUTOMATED_TEXT_EXTRACTION_REVIEW_REQUIRED"}}'::jsonb),
  ('CEV2_EF06MA03_OPERACOES_01', 'central-estudos-v2-candidate-2026-10-25.2', 'MATHEMATICS', 6, 'EF06MA03', 'ba11f423641306dead1fcc544d2150a27df21482fa28da62b3feb48a51c98edc', '{"journeyCode":"CEV2_EF06MA03_OPERACOES_01","journeyTitle":"Estratégias com números naturais","subject":"MATHEMATICS","grade":6,"officialSkillCode":"EF06MA03","skill":"MATH_NATURAL_OPERATIONS_STRATEGIES","unitCode":"MAT_NUMEROS","unitTitle":"Números e operações","officialText":"Resolver e elaborar problemas que envolvam cálculos (mentais ou escritos, exatos ou aproximados) com números naturais, por meio de estratégias variadas, com compreensão dos processos neles envolvidos com e sem uso de calculadora.","lesson":{"title":"Escolher uma estratégia para calcular","estimatedMinutes":20,"introduction":"A biblioteca da escola recebeu 8 caixas com 24 livros em cada uma. Antes de calcular, vale perguntar: há uma maneira de decompor 24 para facilitar a multiplicação? E como conferir se o total faz sentido?","explanation":"Números naturais podem ser calculados por decomposição, estimativa, algoritmos escritos e calculadora. A estratégia deve preservar o valor da operação e deixar claros os passos. Na multiplicação, por exemplo, 24 pode ser pensado como 20 + 4. Em problemas com mais de uma operação, leia a situação para decidir a ordem; parênteses e a relação entre os dados ajudam a organizar o raciocínio.","workedExample":{"prompt":"Uma escola organiza 6 fileiras com 18 cadeiras. Quantas cadeiras são?","steps":["Decomponha 18 em 10 + 8.","Calcule 6 × 10 = 60 e 6 × 8 = 48.","Some 60 + 48 = 108.","Confira: 6 grupos de cerca de 20 devem dar um pouco mais que 100."],"answer":"108 cadeiras."},"guidedPractice":[{"prompt":"Calcule 7 × 25 usando 25 = 100 ÷ 4.","scaffold":"Multiplique 7 por 100 e depois divida o resultado por 4."},{"prompt":"Estime 398 + 205 antes de achar o total exato.","scaffold":"Aproximar 398 para 400 ajuda a conferir a ordem de grandeza."},{"prompt":"Explique por que 4 × (30 + 2) é igual a 4 × 30 + 4 × 2.","scaffold":"Considere quatro grupos, cada um com 30 e mais 2."}],"application":[{"context":"Organização escolar","prompt":"Uma excursão leva 7 ônibus com 42 lugares. Se 268 estudantes vão participar, quantos lugares ficam vazios? Registre as operações e confira por estimativa."},{"context":"Consumo consciente","prompt":"Uma campanha juntou 36 pacotes com 25 folhas cada. Quantas folhas foram reunidas? Compare uma decomposição com o uso de calculadora."}],"review":["Identifique quais quantidades o problema relaciona.","Escolha cálculo mental, decomposição, algoritmo ou calculadora conforme a situação.","Em problemas com várias operações, explique a ordem escolhida.","Use estimativa para conferir se o resultado é razoável.","Responda com a unidade pedida."],"learningCheck":{"passRule":"A revisão técnica verifica cada resposta; a revisão pedagógica humana permanece pendente.","questionIds":["cev2-ef06ma03-q1","cev2-ef06ma03-q2","cev2-ef06ma03-q3","cev2-ef06ma03-q4","cev2-ef06ma03-q5"]}},"questions":[{"id":"cev2-ef06ma03-q1","purpose":"PROBE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Uma sala tem 6 fileiras com 14 carteiras em cada. Qual cálculo representa o total?","options":["6 + 14","6 × 14","14 − 6","14 ÷ 6"],"correctAnswer":"6 × 14","explanation":"Há seis grupos iguais de 14 carteiras; por isso, a multiplicação representa a situação.","misconception":"Somar os dois números como se cada fileira tivesse apenas uma carteira adicional.","officialSkillCode":"EF06MA03"},{"id":"cev2-ef06ma03-q2","purpose":"PRACTICE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Qual é uma decomposição correta de 32 × 5 que facilita o cálculo?","options":["(30 × 5) + (2 × 5)","30 × 2 + 5","32 + 5","32 × 2 + 5"],"correctAnswer":"(30 × 5) + (2 × 5)","explanation":"A propriedade distributiva permite separar 32 em 30 + 2: 150 + 10 = 160.","misconception":"Multiplicar apenas uma das partes da decomposição.","officialSkillCode":"EF06MA03"},{"id":"cev2-ef06ma03-q3","purpose":"TRANSFER","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Uma feira vendeu 128 ingressos pela manhã e 96 à tarde. Depois, 35 ingressos foram cancelados. Quantos permaneceram válidos?","options":["259","189","224","61"],"correctAnswer":"189","explanation":"Some as vendas: 128 + 96 = 224. Depois retire os 35 cancelados: 224 − 35 = 189.","misconception":"Subtrair os cancelamentos antes de juntar as duas vendas.","officialSkillCode":"EF06MA03"},{"id":"cev2-ef06ma03-q4","purpose":"LOCK_IN","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Uma estudante calcula 4 × (20 + 3) e obtém 80 + 3 = 83. Qual correção preserva a multiplicação por 4?","options":["4 × 20 + 4 × 3 = 92","4 + 20 + 3 = 27","20 + 3 × 4 = 32","4 × 20 − 3 = 77"],"correctAnswer":"4 × 20 + 4 × 3 = 92","explanation":"Os quatro grupos contêm tanto 20 quanto 3: 80 + 12 = 92.","misconception":"Distribuir o fator 4 somente para a primeira parcela.","officialSkillCode":"EF06MA03"},{"id":"cev2-ef06ma03-q5","purpose":"REVIEW","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Sem calcular exatamente, qual faixa é mais plausível para 49 × 21?","options":["Menos de 100","Entre 900 e 1.200","Entre 200 e 400","Mais de 5.000"],"correctAnswer":"Entre 900 e 1.200","explanation":"49 × 21 fica perto de 50 × 20 = 1.000; a estimativa ajuda a detectar erros de ordem de grandeza.","misconception":"Tratar 49 × 21 como uma soma ou ignorar o tamanho dos fatores.","officialSkillCode":"EF06MA03"}],"version":"central-estudos-v2-candidate-2026-10-25.2","stage":"ENSINO_FUNDAMENTAL","contentAuthoringStatus":"TECH_VALIDATED_PENDING_REVIEW","pedagogicalReviewStatus":"PEDAGOGICAL_REVIEW_PENDING","publicationStatus":"STAGING","officialSource":{"id":"BNCC_EI_EF_2018","documentVersion":"BNCC Educação Infantil e Ensino Fundamental, versão final 2018","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","catalogPath":"content/bncc/official/catalog-2018.json","repositoryExtractionStatus":"AUTOMATED_TEXT_EXTRACTION_REVIEW_REQUIRED"}}'::jsonb),
  ('CEV2_EF06MA07_FRACOES_01', 'central-estudos-v2-candidate-2026-10-25.2', 'MATHEMATICS', 6, 'EF06MA07', '6f256ad553188da985a649f89ea62e095e674ab3eab06522cee7931ff76ba873', '{"journeyCode":"CEV2_EF06MA07_FRACOES_01","journeyTitle":"Frações: partes, comparação e equivalência","subject":"MATHEMATICS","grade":6,"officialSkillCode":"EF06MA07","skill":"MATH_FRACTION_MEANING_COMPARISON","unitCode":"MAT_NUMEROS","unitTitle":"Números e operações","officialText":"Compreender, comparar e ordenar frações associadas às ideias de partes de inteiros e resultado de divisão, identificando frações equivalentes.","lesson":{"title":"Comparar frações com significado","estimatedMinutes":20,"introduction":"Duas equipes dividiram barras de cereal iguais. Uma recebeu 3/4 de uma barra e outra, 5/8. A escrita parece diferente; para decidir quem recebeu mais, primeiro precisamos comparar partes do mesmo tamanho.","explanation":"O denominador informa em quantas partes iguais o inteiro foi dividido; o numerador indica quantas dessas partes estão sendo consideradas. Frações equivalentes representam a mesma quantidade, mesmo com numeradores e denominadores diferentes. Para comparar, use uma representação, frações equivalentes ou uma referência como 1/2 e 1 inteiro. O inteiro comparado precisa ter o mesmo tamanho.","workedExample":{"prompt":"Qual é maior: 3/4 ou 5/8?","steps":["Escreva 3/4 em oitavos: multiplique numerador e denominador por 2.","3/4 = 6/8.","Compare 6/8 e 5/8: os inteiros estão divididos em partes do mesmo tamanho.","Como 6/8 > 5/8, então 3/4 > 5/8."],"answer":"3/4 é maior que 5/8."},"guidedPractice":[{"prompt":"Represente 2/3 e 4/6 em uma reta ou desenho.","scaffold":"Divida o mesmo inteiro em 3 ou 6 partes iguais e compare a porção."},{"prompt":"Compare 5/6 com 1/2 sem transformar para decimal.","scaffold":"Metade de 6 partes iguais são 3 partes."},{"prompt":"Ordene 1/4, 3/4 e 1/2.","scaffold":"Escreva todas em oitavos ou use a posição entre 0 e 1."}],"application":[{"context":"Receita","prompt":"Uma receita usa 2/3 de xícara de água; outra usa 3/4. Qual usa mais? Mostre uma comparação que mantenha o mesmo tamanho de xícara."},{"context":"Leitura de dados","prompt":"Em uma votação, 4/8 da turma escolheu leitura e 3/6 escolheu desenho. As frações representam quantidades diferentes? Explique."}],"review":["Compare frações de inteiros de mesmo tamanho.","O denominador indica o tamanho das partes iguais.","Frações equivalentes nomeiam a mesma quantidade.","Use uma representação, equivalência ou referência conhecida.","Confira se a comparação responde à pergunta."],"learningCheck":{"passRule":"A revisão técnica verifica cada resposta; a revisão pedagógica humana permanece pendente.","questionIds":["cev2-ef06ma07-q1","cev2-ef06ma07-q2","cev2-ef06ma07-q3","cev2-ef06ma07-q4","cev2-ef06ma07-q5"]}},"questions":[{"id":"cev2-ef06ma07-q1","purpose":"PROBE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Em uma figura dividida em 8 partes iguais, 3 estão pintadas. Qual fração representa a parte pintada?","options":["3/8","8/3","5/8","3/5"],"correctAnswer":"3/8","explanation":"O numerador conta as partes pintadas; o denominador conta todas as partes iguais do inteiro.","misconception":"Inverter numerador e denominador ou contar somente as partes sem pintar.","officialSkillCode":"EF06MA07"},{"id":"cev2-ef06ma07-q2","purpose":"PRACTICE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Qual fração é equivalente a 2/3?","options":["4/6","3/4","2/6","5/6"],"correctAnswer":"4/6","explanation":"Multiplicar numerador e denominador de 2/3 por 2 produz 4/6 sem alterar a quantidade.","misconception":"Alterar só o numerador ou só o denominador.","officialSkillCode":"EF06MA07"},{"id":"cev2-ef06ma07-q3","purpose":"TRANSFER","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Lia percorreu 5/8 de uma trilha e Caio percorreu 3/4 da mesma trilha. Quem percorreu mais?","options":["Lia","Caio","Percorreram a mesma distância","Não é possível comparar, pois os denominadores diferem"],"correctAnswer":"Caio","explanation":"3/4 equivale a 6/8; assim, 6/8 é maior que 5/8.","misconception":"Comparar apenas os denominadores ou os numeradores isoladamente.","officialSkillCode":"EF06MA07"},{"id":"cev2-ef06ma07-q4","purpose":"LOCK_IN","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Qual explicação mostra por que 2/5 é menor que 4/5?","options":["As partes têm o mesmo tamanho e 2 partes são menos que 4","O denominador 5 é menor que 4","2/5 é maior porque 2 é par","Frações com numeradores diferentes não podem ser comparadas"],"correctAnswer":"As partes têm o mesmo tamanho e 2 partes são menos que 4","explanation":"Com denominadores iguais, as partes unitárias têm o mesmo tamanho; compare quantas partes foram tomadas.","misconception":"Confundir o tamanho do denominador com a quantidade representada.","officialSkillCode":"EF06MA07"},{"id":"cev2-ef06ma07-q5","purpose":"REVIEW","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Qual afirmação é verdadeira para 1/2 e 3/6?","options":["Representam a mesma quantidade","1/2 é maior porque tem denominador menor","3/6 é maior porque tem numerador maior","Só seriam iguais se os denominadores fossem iguais"],"correctAnswer":"Representam a mesma quantidade","explanation":"3/6 simplifica para 1/2; as duas frações ocupam o mesmo ponto na reta numérica.","misconception":"Achar que a forma escrita determina a quantidade sem considerar equivalência.","officialSkillCode":"EF06MA07"}],"version":"central-estudos-v2-candidate-2026-10-25.2","stage":"ENSINO_FUNDAMENTAL","contentAuthoringStatus":"TECH_VALIDATED_PENDING_REVIEW","pedagogicalReviewStatus":"PEDAGOGICAL_REVIEW_PENDING","publicationStatus":"STAGING","officialSource":{"id":"BNCC_EI_EF_2018","documentVersion":"BNCC Educação Infantil e Ensino Fundamental, versão final 2018","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","catalogPath":"content/bncc/official/catalog-2018.json","repositoryExtractionStatus":"AUTOMATED_TEXT_EXTRACTION_REVIEW_REQUIRED"}}'::jsonb),
  ('CEV2_EF06MA13_PERCENTUAL_01', 'central-estudos-v2-candidate-2026-10-25.2', 'MATHEMATICS', 6, 'EF06MA13', '04574b6b35d9fc06fe2d26109a60a7ee932d5b3dd64938c71539375d7ef14432', '{"journeyCode":"CEV2_EF06MA13_PERCENTUAL_01","journeyTitle":"Percentuais sem regra de três","subject":"MATHEMATICS","stage":"ENSINO_FUNDAMENTAL","grade":6,"officialSkillCode":"EF06MA13","skill":"MATH_PERCENT_OF_QUANTITY","version":"central-estudos-v2-candidate-2026-10-25.2","contentAuthoringStatus":"TECH_VALIDATED_PENDING_REVIEW","pedagogicalReviewStatus":"PEDAGOGICAL_REVIEW_PENDING","publicationStatus":"STAGING","lesson":{"title":"Descobrir o percentual antes de calcular","estimatedMinutes":18,"introduction":"Uma turma está organizando uma feira e compara preços de materiais. Uma placa informa que um kit de R$ 80 está com 25% de desconto. Antes de usar uma fórmula, pense: 25% representa quantas partes de cada cem? E qual quantidade é o todo nesta situação?","explanation":"Por cento significa por cem. A porcentagem descreve uma relação entre uma parte e um todo. Para calcular uma porcentagem de um valor, identifique primeiro a base: é sobre qual quantidade a taxa incide? Depois, escolha uma estratégia proporcional. Em 25%, podemos pensar em um quarto; em 50%, na metade; em 10%, dividir por dez. Estratégias pessoais e cálculo mental ajudam a compreender; a calculadora pode conferir o resultado. Não é necessário montar regra de três para resolver os problemas desta jornada.","workedExample":{"prompt":"Um kit custa R$ 80 e recebe 25% de desconto. Qual é o desconto e qual é o preço final?","steps":["A base é R$ 80, pois o desconto incide sobre o preço do kit.","25% é um quarto. Um quarto de 80 é 80 ÷ 4 = 20.","O desconto é R$ 20. O preço final é 80 − 20 = R$ 60.","Confira: 50% de 80 seria 40; 25% deve ser a metade disso, 20."],"answer":"Desconto de R$ 20; preço final de R$ 60."},"guidedPractice":[{"prompt":"Calcule 10% de R$ 90. Qual operação mental pode ajudar?","scaffold":"10% corresponde a uma décima parte."},{"prompt":"Uma garrafa de 2 litros está com 50% do conteúdo. Quantos litros há?","scaffold":"50% corresponde à metade do todo."},{"prompt":"Compare 20% de 150 com 10% de 150. O que muda e o que continua igual?","scaffold":"Use a mesma base e compare as taxas."}],"application":[{"context":"Educação financeira","prompt":"Uma mochila custa R$ 120. A loja oferece 15% de desconto. Registre a base, encontre o desconto e determine o preço final. Explique uma estratégia sem regra de três."},{"context":"Leitura de informação","prompt":"Em uma pesquisa com 200 estudantes, 30% preferiram ir à feira de bicicleta. Quantos estudantes são esse grupo? Explique por que 30% não significa 30 estudantes."}],"review":["Porcentagem é uma relação por cem.","A base é o todo sobre o qual a taxa incide.","Use frações familiares, decomposição ou cálculo mental para encontrar a parte.","Em desconto, subtraia a parte encontrada do preço inicial.","Confira se o resultado é razoável e se responde exatamente à pergunta."],"learningCheck":{"passRule":"Responda corretamente a pelo menos 4 das 5 questões; erros mostram explicação e permitem nova tentativa.","questionIds":["cev2-ef06ma13-probe-01","cev2-ef06ma13-practice-02","cev2-ef06ma13-transfer-03","cev2-ef06ma13-lock-in-04","cev2-ef06ma13-review-05"]}},"questions":[{"id":"cev2-ef06ma13-probe-01","purpose":"PROBE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Uma caixa tem 40 lápis. Quantos lápis correspondem a 25% do total?","options":["5 lápis","10 lápis","25 lápis","30 lápis"],"correctAnswer":"10 lápis","calculation":{"operation":"PERCENT_OF","base":40,"percent":25,"expectedNumeric":10},"explanation":"25% é um quarto; 40 ÷ 4 = 10.","misconception":"Confundir a taxa 25 com a quantidade de lápis ou calcular 25% como 25 unidades."},{"id":"cev2-ef06ma13-practice-02","purpose":"PRACTICE","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Uma turma arrecadou R$ 90. Qual valor corresponde a 10% dessa quantia?","options":["R$ 9","R$ 10","R$ 80","R$ 90"],"correctAnswer":"R$ 9","calculation":{"operation":"PERCENT_OF","base":90,"percent":10,"expectedNumeric":9},"explanation":"10% é a décima parte da base: 90 ÷ 10 = 9.","misconception":"Tratar a taxa percentual como o valor final."},{"id":"cev2-ef06ma13-transfer-03","purpose":"TRANSFER","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Uma conta de R$ 150 recebeu desconto de 20%. Qual será o preço depois do desconto?","options":["R$ 30","R$ 120","R$ 130","R$ 180"],"correctAnswer":"R$ 120","calculation":{"operation":"PRICE_AFTER_DISCOUNT","base":150,"percent":20,"expectedNumeric":120},"explanation":"20% de 150 é 30; subtraindo o desconto da base: 150 − 30 = 120.","misconception":"Responder com o valor do desconto em vez do preço final."},{"id":"cev2-ef06ma13-lock-in-04","purpose":"LOCK_IN","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Em uma pesquisa com 200 estudantes, 30% escolheram uma atividade. Quantos estudantes fizeram essa escolha?","options":["30","60","170","230"],"correctAnswer":"60","calculation":{"operation":"PERCENT_OF","base":200,"percent":30,"expectedNumeric":60},"explanation":"10% de 200 é 20; três grupos de 10% correspondem a 30%, então 3 × 20 = 60.","misconception":"Ler 30% como 30 estudantes sem considerar o tamanho do grupo."},{"id":"cev2-ef06ma13-review-05","purpose":"REVIEW","interactionType":"SINGLE_CHOICE","difficulty":"EASY","statement":"Qual estratégia encontra 5% de 80 sem regra de três?","options":["Calcular 10% de 80 e dividir o resultado por 2","Somar 5 a 80","Dividir 80 por 5 e chamar o resultado de 5%","Subtrair 5 de 80"],"correctAnswer":"Calcular 10% de 80 e dividir o resultado por 2","calculation":{"operation":"PERCENT_OF","base":80,"percent":5,"expectedNumeric":4},"explanation":"10% de 80 é 8; metade de 8 é 4, portanto 5% de 80 é 4.","misconception":"Usar o número da taxa como se fosse uma operação direta sobre o total."},{"id":"cev2-ef06ma13-practice-06","purpose":"PRACTICE","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Um livro custa R$ 120 e tem desconto de 15%. Qual é o valor do desconto?","options":["R$ 15","R$ 18","R$ 102","R$ 105"],"correctAnswer":"R$ 18","calculation":{"operation":"PERCENT_OF","base":120,"percent":15,"expectedNumeric":18},"explanation":"10% de 120 é 12 e 5% é 6; juntos, 15% correspondem a R$ 18.","misconception":"Confundir desconto com preço final."},{"id":"cev2-ef06ma13-transfer-07","purpose":"TRANSFER","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Uma escola tem 250 mudas e 40% serão plantadas no primeiro dia. Quantas mudas serão plantadas?","options":["40","100","210","290"],"correctAnswer":"100","calculation":{"operation":"PERCENT_OF","base":250,"percent":40,"expectedNumeric":100},"explanation":"10% de 250 é 25; quatro grupos de 25 formam 40%, isto é, 100 mudas.","misconception":"Tomar o valor numérico 40 como a quantidade de mudas."},{"id":"cev2-ef06ma13-lock-in-08","purpose":"LOCK_IN","interactionType":"SINGLE_CHOICE","difficulty":"MEDIUM","statement":"Uma mochila de R$ 80 recebeu aumento de 10%. Qual é o novo preço?","options":["R$ 8","R$ 70","R$ 88","R$ 90"],"correctAnswer":"R$ 88","calculation":{"operation":"PRICE_AFTER_INCREASE","base":80,"percent":10,"expectedNumeric":88},"explanation":"10% de 80 é R$ 8. No aumento, somamos a variação à base: 80 + 8 = 88.","misconception":"Responder apenas com o valor do aumento."}],"unitCode":"MAT_NUMEROS_RACIONAIS","unitTitle":"Números racionais e proporcionalidade"}'::jsonb)
on conflict (journey_code, content_version) do nothing;

create or replace function public.get_central_studies_v2_review_queue_v1()
returns table(
  journey_code text, content_version text, subject_area text, grade_level smallint,
  official_skill_code text, title text, snapshot_fingerprint text, review_status text,
  publication_status text, reviewer_name text, reviewer_email text, reviewed_at timestamptz,
  review_notes text, updated_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_platform_super_admin() then
    raise exception 'CENTRAL_STUDIES_V2_REVIEW_FORBIDDEN' using errcode = '42501';
  end if;
  return query
    select candidate.journey_code, candidate.content_version, candidate.subject_area, candidate.grade_level,
           candidate.official_skill_code, candidate.payload->>'journeyTitle', candidate.snapshot_fingerprint,
           candidate.review_status, candidate.publication_status, candidate.reviewer_name, candidate.reviewer_email,
           candidate.reviewed_at, candidate.review_notes, candidate.updated_at
      from public.learning_central_studies_v2_candidates candidate
     order by candidate.subject_area, candidate.grade_level, candidate.journey_code;
end;
$$;

create or replace function public.get_central_studies_v2_review_preview_v1(
  p_journey_code text, p_content_version text
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_candidate public.learning_central_studies_v2_candidates%rowtype;
begin
  if not public.is_platform_super_admin() then
    raise exception 'CENTRAL_STUDIES_V2_REVIEW_FORBIDDEN' using errcode = '42501';
  end if;
  select * into v_candidate from public.learning_central_studies_v2_candidates candidate
   where candidate.journey_code = p_journey_code and candidate.content_version = p_content_version;
  if not found then raise exception 'CENTRAL_STUDIES_V2_CANDIDATE_NOT_FOUND' using errcode = 'P0002'; end if;
  return pg_catalog.jsonb_build_object(
    'journey_code', v_candidate.journey_code, 'content_version', v_candidate.content_version,
    'subject_area', v_candidate.subject_area, 'grade_level', v_candidate.grade_level,
    'official_skill_code', v_candidate.official_skill_code, 'snapshot_fingerprint', v_candidate.snapshot_fingerprint,
    'review_status', v_candidate.review_status, 'publication_status', v_candidate.publication_status,
    'reviewer_name', v_candidate.reviewer_name, 'reviewer_email', v_candidate.reviewer_email,
    'reviewed_at', v_candidate.reviewed_at, 'review_notes', v_candidate.review_notes, 'payload', v_candidate.payload
  );
end;
$$;

create or replace function public.review_central_studies_v2_candidate_v1(
  p_journey_code text, p_content_version text, p_decision text, p_notes text,
  p_expected_fingerprint text, p_checklist jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_candidate public.learning_central_studies_v2_candidates%rowtype;
  v_profile public.profiles%rowtype;
  v_name text;
  v_event_id uuid;
begin
  if not public.is_platform_super_admin() then
    raise exception 'CENTRAL_STUDIES_V2_REVIEW_FORBIDDEN' using errcode = '42501';
  end if;
  if p_decision is null or p_decision not in ('APPROVED_FOR_INTEGRATION', 'CHANGES_REQUESTED')
     or length(btrim(coalesce(p_notes, ''))) < 10 or length(p_notes) > 2000 then
    raise exception 'CENTRAL_STUDIES_V2_REVIEW_INVALID_DECISION' using errcode = '22023';
  end if;
  if p_decision = 'APPROVED_FOR_INTEGRATION' and (
    p_checklist is null or pg_catalog.jsonb_typeof(p_checklist) is distinct from 'object'
    or p_checklist->>'officialAlignment' is distinct from 'true'
    or p_checklist->>'pedagogicalAccuracy' is distinct from 'true'
    or p_checklist->>'ageAndGradeSuitability' is distinct from 'true'
    or p_checklist->>'clarityAndAccessibility' is distinct from 'true'
    or p_checklist->>'answerQuality' is distinct from 'true'
    or p_checklist->>'culturalAndContextualSuitability' is distinct from 'true'
  ) then
    raise exception 'CENTRAL_STUDIES_V2_REVIEW_CHECKLIST_INCOMPLETE' using errcode = '22023';
  end if;
  select * into v_candidate from public.learning_central_studies_v2_candidates candidate
   where candidate.journey_code = p_journey_code and candidate.content_version = p_content_version
   for update;
  if not found then raise exception 'CENTRAL_STUDIES_V2_CANDIDATE_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_candidate.snapshot_fingerprint is distinct from p_expected_fingerprint then
    raise exception 'CENTRAL_STUDIES_V2_CONTENT_CHANGED' using errcode = '40001';
  end if;
  if v_candidate.review_status = 'PEDAGOGICAL_REVIEWED' then
    raise exception 'CENTRAL_STUDIES_V2_APPROVED_VERSION_IMMUTABLE' using errcode = '55000';
  end if;
  select * into v_profile from public.profiles profile where profile.id = auth.uid();
  v_name := coalesce(nullif(btrim(v_profile.full_name), ''), v_profile.email, auth.uid()::text);
  insert into public.learning_central_studies_v2_review_events(
    candidate_id, journey_code, content_version, snapshot_fingerprint, decision, notes, checklist,
    reviewer_profile_id, reviewer_id_snapshot, reviewer_name, reviewer_email
  ) values (
    v_candidate.id, v_candidate.journey_code, v_candidate.content_version, v_candidate.snapshot_fingerprint,
    p_decision, btrim(p_notes), coalesce(p_checklist, '{}'::jsonb), v_profile.id, auth.uid(), v_name,
    coalesce(v_profile.email, '')
  ) returning id into v_event_id;
  update public.learning_central_studies_v2_candidates
     set review_status = case when p_decision = 'APPROVED_FOR_INTEGRATION' then 'PEDAGOGICAL_REVIEWED' else 'CHANGES_REQUESTED' end,
         reviewer_profile_id = v_profile.id, reviewer_id_snapshot = auth.uid(), reviewer_name = v_name,
         reviewer_email = coalesce(v_profile.email, ''), reviewed_at = now(), review_notes = btrim(p_notes),
         review_checklist = coalesce(p_checklist, '{}'::jsonb), updated_at = now()
   where id = v_candidate.id;
  return pg_catalog.jsonb_build_object(
    'review_event_id', v_event_id, 'journey_code', v_candidate.journey_code,
    'content_version', v_candidate.content_version, 'decision', p_decision,
    'publication_status', 'STAGING', 'reviewer_name', v_name, 'reviewer_email', coalesce(v_profile.email, ''),
    'reviewed_at', now(), 'snapshot_fingerprint', v_candidate.snapshot_fingerprint
  );
end;
$$;

revoke all on function public.get_central_studies_v2_review_queue_v1() from public, anon;
revoke all on function public.get_central_studies_v2_review_preview_v1(text, text) from public, anon;
revoke all on function public.review_central_studies_v2_candidate_v1(text, text, text, text, text, jsonb) from public, anon;
grant execute on function public.get_central_studies_v2_review_queue_v1() to authenticated;
grant execute on function public.get_central_studies_v2_review_preview_v1(text, text) to authenticated;
grant execute on function public.review_central_studies_v2_candidate_v1(text, text, text, text, text, jsonb) to authenticated;

comment on table public.learning_central_studies_v2_candidates is 'Versioned Central de Estudos V2 content candidates. Only Super Admin RPCs can read or record human reviews; candidate approvals do not publish to students.';
comment on table public.learning_central_studies_v2_review_events is 'Append-only audit history for human Central de Estudos V2 content review.';

commit;
